import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.C7GIOALF.js";const u=JSON.parse('{"title":"BANG-Like Hidden Role Formats","description":"","frontmatter":{},"headers":[],"relativePath":"formats/bang-like/index.md","filePath":"formats/bang-like/index.md","lastUpdated":1782025909000}'),d={name:"formats/bang-like/index.md"};function o(n,e,i,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="bang-like-hidden-role-formats" tabindex="-1">BANG-Like Hidden Role Formats <a class="header-anchor" href="#bang-like-hidden-role-formats" aria-label="Permalink to &quot;BANG-Like Hidden Role Formats&quot;">​</a></h1><p><a href="./../">All formats</a></p><p>These games add secret roles and competing objectives to multiplayer Magic. Choose a complete version below. The leader&#39;s bonus, role visibility, rewards, and victory rules vary by version.</p><table tabindex="0"><thead><tr><th>Ruleset</th><th>Players</th><th>Roles and distinguishing rules</th></tr></thead><tbody><tr><td><a href="./variants/bang-magic.html">BANG! Magic</a></td><td>5–7+, with agreed role counts</td><td>Sheriff, Deputy, Outlaw, Renegade; simple hidden roles.</td></tr><tr><td><a href="./variants/kingdoms.html">Kingdoms</a></td><td>5–6</td><td>Basic-land role cards; the Usurper can replace the King.</td></tr><tr><td><a href="./variants/kingdom-bang-edh.html">Kingdom / BANG EDH</a></td><td>5–6</td><td>Emperor bonuses, Assassin rewards, Guard penalty, and a source ambiguity in the Rogue&#39;s victory wording.</td></tr><tr><td><a href="./variants/treachery.html">MTG Treachery</a></td><td>4+, with published setups through 8</td><td>Custom Identity cards, unveil abilities, and formal team rules.</td></tr></tbody></table><h2 id="related-boxed-sets" tabindex="-1">Related boxed sets <a class="header-anchor" href="#related-boxed-sets" aria-label="Permalink to &quot;Related boxed sets&quot;">​</a></h2><p><a href="./../../boxed-sets/feudalism.html">Feudalism</a> is a draft monarch-focused box. Its page records the recurring crown rule and the base-version and role decisions still needed.</p><p>A hidden-role box normally needs role cards, a player-count chart, the chosen ruleset, and any extra reminder cards. Unless its rules explicitly tie a deck to a role, each included deck should function with any role.</p><h2 id="reference-notes" tabindex="-1">Reference notes <a class="header-anchor" href="#reference-notes" aria-label="Permalink to &quot;Reference notes&quot;">​</a></h2><p>The <a href="./../../sources/#bang-like-hidden-roles">source index</a> links the original posts and archived research. Those references stay separate from the rules pages above.</p>',9)])])}const p=t(d,[["render",o]]);export{u as __pageData,p as default};
